import type { AgendaEvent } from '@motivation/shared';

export const AGENDA_EVENTS = {
    /** Story 402: an unmatched calendar event should become a workout rule; the screen asks how. */
    TRACK_WORKOUT: 'agenda:track-workout',
} as const;

export interface AgendaEventMap {
    [AGENDA_EVENTS.TRACK_WORKOUT]: { event: AgendaEvent };
}

export type AgendaDomEvent<K extends keyof AgendaEventMap> = CustomEvent<AgendaEventMap[K]>;

export function createAgendaEvent<K extends keyof AgendaEventMap>(
    type: K,
    detail: AgendaEventMap[K],
): AgendaDomEvent<K> {
    return new CustomEvent(type, {
        bubbles: true,
        composed: true,
        detail,
    }) as AgendaDomEvent<K>;
}

export const createTrackWorkoutEvent = (detail: AgendaEventMap[typeof AGENDA_EVENTS.TRACK_WORKOUT]) =>
    createAgendaEvent(AGENDA_EVENTS.TRACK_WORKOUT, detail);

export type TrackWorkoutEvent = AgendaDomEvent<typeof AGENDA_EVENTS.TRACK_WORKOUT>;

declare global {
    interface HTMLElementEventMap {
        [AGENDA_EVENTS.TRACK_WORKOUT]: TrackWorkoutEvent;
    }
}
