import { ACTIVITY_TYPES, type ActivityType } from '@motivation/shared';
import type { ScreenComponent } from '../../../types/screen-component.js';
import { createScreenStatusNodes, createScreenStatusMixin } from '../../_shared/screen-status.js';
import { createComponentLogger } from '../../../utils/component-logger.js';
import { documentStyleSheet } from '../../../utils/css.js';
import { safeExec } from '../../../utils/safe-exec.js';
import { AgendaService } from '../../../services/agenda.service.js';
import {
    CalendarWorkoutRulesService,
    calendarWorkoutRulesService as defaultRulesService,
} from '../../../services/calendar-workout-rules.service.js';
import { activityTypeLabel } from '../../health/health-utils.js';
import { AGENDA_EVENTS, type TrackWorkoutEvent } from '../agenda-events.js';
import type { AgendaList } from '../agenda-list/agenda-list.component.js';
import '../agenda-list/agenda-list.component.js';
import screenStyles from './agenda-screen.css?inline';

documentStyleSheet(screenStyles);

const template = document.createElement('template');
template.innerHTML = `
    <dialog class="track-workout-dialog" data-testid="track-workout-dialog">
        <form method="dialog" data-testid="track-workout-form">
            <h2>Track as workout</h2>
            <div class="form-group">
                <label for="track-match">Events containing</label>
                <input type="text" id="track-match" name="match" required data-testid="track-match">
            </div>
            <div class="form-group">
                <label for="track-type">Type</label>
                <select id="track-type" name="type" data-testid="track-type">
                    ${ACTIVITY_TYPES.map((type) => `<option value="${type}">${activityTypeLabel(type)}</option>`).join('')}
                </select>
            </div>
            <pre class="screen-error" data-testid="track-error" hidden></pre>
            <div class="form-actions">
                <button type="button" value="cancel" data-testid="track-cancel">Cancel</button>
                <button type="submit" data-testid="track-save">Save</button>
            </div>
        </form>
    </dialog>
`;

export class AgendaScreen extends HTMLElement implements ScreenComponent {
    private initialized = false;
    private agendaList!: AgendaList;
    private dialog!: HTMLDialogElement;
    private rulesService: CalendarWorkoutRulesService = defaultRulesService;
    private statusNodes = createScreenStatusNodes();
    private statusMixin = createScreenStatusMixin(this.statusNodes.loadingNode, this.statusNodes.errorNode, this.statusNodes.retryNode);
    private readonly log = createComponentLogger('agenda-screen');

    setRulesService(service: CalendarWorkoutRulesService): void {
        this.rulesService = service;
    }

    connectedCallback(): void {
        if (!this.initialized) {
            this.initialized = true;
            this.classList.add('view-section');
            this.id = 'agenda-view';
            this.buildDom();
        }
        void this.refresh();
    }

    private buildDom(): void {
        this.statusNodes.loadingNode.textContent = 'Loading agenda…';
        this.statusNodes.errorNode.dataset.testid = 'agenda-error';
        this.statusNodes.retryNode.dataset.testid = 'agenda-retry';
        this.statusNodes.retryNode.addEventListener('click', () => { void this.refresh(); });

        this.agendaList = document.createElement('agenda-list') as AgendaList;
        this.agendaList.addEventListener(AGENDA_EVENTS.TRACK_WORKOUT, (e: TrackWorkoutEvent) => this.openTrackDialog(e.detail.event.summary ?? ''));

        this.append(this.statusNodes.loadingNode, this.statusNodes.errorNode, this.statusNodes.retryNode, this.agendaList);
        this.append(template.content.cloneNode(true));

        this.dialog = this.querySelector<HTMLDialogElement>('[data-testid="track-workout-dialog"]')!;
        const form = this.querySelector<HTMLFormElement>('[data-testid="track-workout-form"]')!;
        form.addEventListener('submit', (e) => {
            e.preventDefault();
            void this.saveRule(form);
        });
        this.querySelector('[data-testid="track-cancel"]')!.addEventListener('click', () => this.dialog.close());
    }

    async refresh(): Promise<void> {
        return safeExec(this, this.log, async () => {
            const [events, rules] = await Promise.all([AgendaService.fetchEvents(), this.rulesService.getRules()]);
            this.agendaList.events = events;
            this.agendaList.rules = rules;
        });
    }

    private openTrackDialog(summary: string): void {
        this.querySelector<HTMLInputElement>('[data-testid="track-match"]')!.value = summary.trim();
        this.querySelector<HTMLSelectElement>('[data-testid="track-type"]')!.value = 'workout';
        this.showTrackError(null);
        this.dialog.showModal();
    }

    private async saveRule(form: HTMLFormElement): Promise<void> {
        const data = new FormData(form);
        try {
            await this.rulesService.addRule({
                match: String(data.get('match') ?? '').trim(),
                type: String(data.get('type')) as ActivityType,
            });
            this.agendaList.rules = await this.rulesService.getRules();
            this.dialog.close();
        } catch (error) {
            this.log.error('saving a calendar workout rule failed:', error);
            this.showTrackError(error);
        }
    }

    private showTrackError(error: unknown): void {
        const el = this.querySelector<HTMLElement>('[data-testid="track-error"]')!;
        el.hidden = error === null;
        el.textContent = error === null ? '' : error instanceof Error ? `${error.message}\n${error.stack ?? ''}` : String(error);
    }

    setLoading(): void {
        this.statusMixin.setLoading();
    }

    setError(err: unknown): void {
        this.statusMixin.setError(err);
        this.statusNodes.errorNode.textContent = `Failed to load agenda\n\n${this.statusNodes.errorNode.textContent}`;
    }

    clearStatus(): void {
        this.statusMixin.clearStatus();
    }
}

if (!customElements.get('agenda-screen')) {
    customElements.define('agenda-screen', AgendaScreen);
}
